import { readdirSync, readFileSync, statSync } from "node:fs";
import { basename, extname, join } from "node:path";

import type { AssertionResult } from "@dec-bench/eval-core";

const WORKSPACE_ROOT = "/workspace";
const IGNORED_DIRS = new Set([
  ".git",
  ".next",
  ".turbo",
  "dist",
  "build",
  "coverage",
  "node_modules",
  "__pycache__",
  ".venv",
  "venv",
]);
const TEXT_FILE_EXTENSIONS = new Set([
  ".py",
  ".js",
  ".jsx",
  ".ts",
  ".tsx",
  ".sql",
  ".sh",
  ".bash",
  ".zsh",
  ".rb",
  ".go",
  ".rs",
  ".java",
  ".yaml",
  ".yml",
  ".json",
  ".toml",
  ".ini",
  ".cfg",
  ".conf",
  ".md",
]);
const DOC_PATHS = [
  join(WORKSPACE_ROOT, "README.md"),
  join(WORKSPACE_ROOT, "README.txt"),
  join(WORKSPACE_ROOT, "docs"),
];
const DEFAULT_CONNECTION_LITERALS = [
  "localhost:5432",
  "localhost:8123",
  "localhost:9000",
  "localhost:9092",
];
const DEFAULT_ENV_TOKENS = [
  "process.env",
  "ctx.env(",
  "os.environ",
  "getenv(",
  "POSTGRES_URL",
  "CLICKHOUSE_URL",
  "REDPANDA_BROKER",
];

interface WorkspaceTextFile {
  path: string;
  relativePath: string;
  content: string;
}

export async function scanWorkspaceForHardcodedConnections(options?: {
  literals?: string[];
  envTokens?: string[];
}): Promise<AssertionResult> {
  const literals = options?.literals ?? DEFAULT_CONNECTION_LITERALS;
  const envTokens = options?.envTokens ?? DEFAULT_ENV_TOKENS;
  const findings: Array<{ file: string; line: number; literal: string }> = [];

  for (const file of collectWorkspaceTextFiles()) {
    const lines = file.content.split(/\r?\n/);
    for (let index = 0; index < lines.length; index += 1) {
      const line = lines[index] ?? "";
      if (!literals.some((literal) => line.includes(literal))) {
        continue;
      }
      if (envTokens.some((token) => line.includes(token))) {
        continue;
      }
      findings.push({
        file: file.relativePath,
        line: index + 1,
        literal: literals.find((literal) => line.includes(literal)) ?? "unknown",
      });
      if (findings.length >= 10) {
        break;
      }
    }
  }

  return {
    passed: findings.length === 0,
    message:
      findings.length === 0
        ? "No hardcoded connection strings found in workspace files."
        : "Hardcoded connection strings found in workspace files.",
    details: {
      findings,
    },
  };
}

export async function hasReadmeOrDocs(): Promise<AssertionResult> {
  const foundPaths = DOC_PATHS.filter((path) => exists(path));
  return {
    passed: foundPaths.length > 0,
    message:
      foundPaths.length > 0
        ? "Workspace includes operator-facing docs or a README."
        : "Workspace is missing a README or docs directory for operator handoff.",
    details: {
      foundPaths,
    },
  };
}

export async function avoidsSelectStarQueries(): Promise<AssertionResult> {
  const findings: Array<{ file: string; line: number }> = [];
  for (const file of collectWorkspaceTextFiles()) {
    const lines = file.content.split(/\r?\n/);
    for (let index = 0; index < lines.length; index += 1) {
      const line = lines[index] ?? "";
      if (!/\bselect\s+\*/i.test(line)) {
        continue;
      }
      findings.push({
        file: file.relativePath,
        line: index + 1,
      });
      if (findings.length >= 10) {
        break;
      }
    }
  }

  return {
    passed: findings.length === 0,
    message:
      findings.length === 0
        ? "Workspace avoids `SELECT *` queries in checked source files."
        : "Workspace still contains `SELECT *` queries in checked source files.",
    details: {
      findings,
    },
  };
}

function collectWorkspaceTextFiles(): WorkspaceTextFile[] {
  const files: WorkspaceTextFile[] = [];
  const visit = (current: string, relativePrefix = "") => {
    for (const entry of readdirSync(current, { withFileTypes: true })) {
      if (entry.isDirectory()) {
        if (IGNORED_DIRS.has(entry.name)) {
          continue;
        }
        visit(join(current, entry.name), join(relativePrefix, entry.name));
        continue;
      }
      if (!entry.isFile()) {
        continue;
      }
      const extension = extname(entry.name).toLowerCase();
      if (!TEXT_FILE_EXTENSIONS.has(extension) && basename(entry.name).toLowerCase() !== "dockerfile") {
        continue;
      }

      const absolutePath = join(current, entry.name);
      if (!isReadableTextFile(absolutePath)) {
        continue;
      }
      files.push({
        path: absolutePath,
        relativePath: join(relativePrefix, entry.name),
        content: readFileSync(absolutePath, "utf8"),
      });
    }
  };

  if (exists(WORKSPACE_ROOT)) {
    visit(WORKSPACE_ROOT);
  }
  return files;
}

function exists(path: string): boolean {
  try {
    return statSync(path).isFile() || statSync(path).isDirectory();
  } catch {
    return false;
  }
}

function isReadableTextFile(path: string): boolean {
  try {
    const stat = statSync(path);
    return stat.isFile() && stat.size <= 512_000;
  } catch {
    return false;
  }
}

import { createServer } from "node:http";

const PORT = Number.parseInt(process.env.PORT ?? "3000", 10);
const CLICKHOUSE_URL = process.env.CLICKHOUSE_URL;
const MAX_LIMIT = 100;
const DEFAULT_LIMIT = 20;
const DEFAULT_OFFSET = 0;

if (!CLICKHOUSE_URL) {
  throw new Error("Missing CLICKHOUSE_URL environment variable.");
}

let totalCache = { value: null, expiresAt: 0 };

function sendJson(res, statusCode, payload) {
  res.writeHead(statusCode, { "content-type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(payload));
}

function parseNonNegativeInt(value, fallback) {
  if (value === null) {
    return fallback;
  }

  if (!/^\d+$/.test(value)) {
    return null;
  }

  return Number.parseInt(value, 10);
}

async function clickhouseQuery(sql) {
  const url = new URL(CLICKHOUSE_URL);
  url.searchParams.set("query", sql);

  const response = await fetch(url, {
    headers: {
      accept: "application/json",
    },
  });

  if (!response.ok) {
    const body = await response.text();
    throw new Error(`ClickHouse query failed with status ${response.status}: ${body}`);
  }

  return response.json();
}

async function getTotalCount() {
  const now = Date.now();
  if (totalCache.value !== null && totalCache.expiresAt > now) {
    return totalCache.value;
  }

  const sql = [
    "SELECT count() AS total",
    "FROM analytics.events",
    "FORMAT JSON",
  ].join("\n");
  const result = await clickhouseQuery(sql);
  const total = Number(result.data?.[0]?.total ?? 0);

  totalCache = {
    value: total,
    expiresAt: now + 30_000,
  };

  return total;
}

async function getEvents(limit, offset) {
  const sql = [
    "SELECT event_id, event_ts, event_type, user_id",
    "FROM analytics.events",
    "ORDER BY event_ts ASC, event_id ASC",
    `LIMIT ${limit}`,
    `OFFSET ${offset}`,
    "FORMAT JSON",
  ].join("\n");

  const result = await clickhouseQuery(sql);
  return Array.isArray(result.data) ? result.data : [];
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`);

  if (req.method === "GET" && url.pathname === "/health") {
    sendJson(res, 200, { ok: true });
    return;
  }

  if (req.method !== "GET" || url.pathname !== "/api/events") {
    sendJson(res, 404, { error: "Not found" });
    return;
  }

  const rawLimit = parseNonNegativeInt(url.searchParams.get("limit"), DEFAULT_LIMIT);
  const rawOffset = parseNonNegativeInt(url.searchParams.get("offset"), DEFAULT_OFFSET);

  if (rawLimit === null || rawOffset === null) {
    sendJson(res, 400, { error: "limit and offset must be non-negative integers" });
    return;
  }

  const limit = Math.min(rawLimit, MAX_LIMIT);
  const offset = rawOffset;

  try {
    const [total, data] = await Promise.all([getTotalCount(), getEvents(limit, offset)]);
    sendJson(res, 200, {
      data,
      total,
      hasMore: offset + data.length < total,
      limit,
      offset,
    });
  } catch (error) {
    sendJson(res, 500, {
      error: "Failed to fetch analytics events",
      details: error instanceof Error ? error.message : String(error),
    });
  }
});

server.listen(PORT, "0.0.0.0", () => {
  console.log(`Analytics API listening on port ${PORT}`);
  getTotalCount().catch(() => {
    // Keep startup resilient if ClickHouse is briefly unavailable.
  });
});
